import Component from "@glimmer/component";
import { cached, tracked } from "@glimmer/tracking";
import { service } from "@ember/service";
import helperFn from "discourse/helpers/helper-fn";
import Composer from "discourse/models/composer";
import DUserLink from "discourse/ui-kit/d-user-link";
import dAvatar from "discourse/ui-kit/helpers/d-avatar";
import { i18n } from "discourse-i18n";

export default class ComposerPresenceDisplay extends Component {
  @service presence;
  @service composerPresenceManager;
  @service currentUser;
  @service siteSettings;

  @tracked replyChannel;
  @tracked whisperChannel;
  @tracked editChannel;
  @tracked translateChannel;

  setupReplyChannel = helperFn((_, on) => {
    const { topic } = this.args.model;

    if (!topic || !this.isReply) {
      return;
    }

    const name = `/discourse-presence/reply/${topic.id}`;
    const replyChannel = this.presence.getChannel(name);
    this.replyChannel = replyChannel;

    replyChannel.subscribe();
    on.cleanup(() => replyChannel.unsubscribe());
  });

  setupWhisperChannel = helperFn((_, on) => {
    const { topic } = this.args.model;
    const { whisperer } = this.currentUser;

    if (!topic || !this.isReply || !whisperer) {
      return;
    }

    const name = `/discourse-presence/whisper/${topic.id}`;
    const whisperChannel = this.presence.getChannel(name);
    this.whisperChannel = whisperChannel;

    whisperChannel.subscribe();
    on.cleanup(() => whisperChannel.unsubscribe());
  });

  setupEditChannel = helperFn((_, on) => {
    const { post } = this.args.model;

    if (!post || !this.isEdit) {
      return;
    }

    const name = `/discourse-presence/edit/${post.id}`;
    const editChannel = this.presence.getChannel(name);
    this.editChannel = editChannel;

    editChannel.subscribe();
    on.cleanup(() => editChannel.unsubscribe());
  });

  setupTranslateChannel = helperFn((_, on) => {
    const { post } = this.args.model;

    if (!post || !this.isTranslate) {
      return;
    }

    const name = `/discourse-presence/translate/${post.id}`;
    const translateChannel = this.presence.getChannel(name);
    this.translateChannel = translateChannel;

    translateChannel.subscribe();
    on.cleanup(() => translateChannel.unsubscribe());
  });

  notifyState = helperFn((_, on) => {
    const { topic, post, replyDirty } = this.args.model;
    const entity = this.isEdit || this.isTranslate ? post : topic;

    if (entity) {
      const name = `/discourse-presence/${this.state}/${entity.id}`;
      this.composerPresenceManager.notifyState(name, replyDirty);
    }

    on.cleanup(() => this.composerPresenceManager.leave());
  });

  get isReply() {
    return this.state === "reply" || this.state === "whisper";
  }

  get isEdit() {
    return this.state === "edit";
  }

  get isTranslate() {
    return this.state === "translate";
  }

  @cached
  get state() {
    const { editingPost, whisper, replyingToTopic, action } = this.args.model;

    if (action === Composer.ADD_TRANSLATION) {
      return "translate";
    } else if (editingPost) {
      return "edit";
    } else if (whisper) {
      return "whisper";
    } else if (replyingToTopic) {
      return "reply";
    }
  }

  @cached
  get users() {
    let users;

    if (this.isEdit) {
      users = this.editChannel?.users || [];
    } else if (this.isTranslate) {
      users = this.translateChannel?.users || [];
    } else {
      const replyUsers = this.replyChannel?.users || [];
      const whisperUsers = this.whisperChannel?.users || [];
      users = [...replyUsers, ...whisperUsers];
    }

    return users
      .filter((u) => u.id !== this.currentUser.id)
      .slice(0, this.siteSettings.presence_max_users_shown);
  }

  <template>
    {{#if this.currentUser}}
      {{this.setupReplyChannel}}
      {{this.setupWhisperChannel}}
      {{this.setupEditChannel}}
      {{this.setupTranslateChannel}}
      {{this.notifyState}}

      {{#if (gt this.users.length 0)}}
        <div class="presence-users">
          <div class="presence-avatars">
            {{#each this.users as |user|}}
              <DUserLink @user={{user}}>
                {{dAvatar user imageSize="small"}}
              </DUserLink>
            {{/each}}
          </div>

          <span class="presence-text">
            <span class="description">
              {{~#if this.isReply~}}
                {{i18n "presence.replying" count=this.users.length}}
              {{~else if this.isTranslate~}}
                {{i18n "presence.translating" count=this.users.length}}
              {{~else~}}
                {{i18n "presence.editing" count=this.users.length}}
              {{~/if~}}
            </span>
            <span class="wave">
              <span class="dot">.</span>
              <span class="dot">.</span>
              <span class="dot">.</span>
            </span>
          </span>
        </div>
      {{/if}}
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { cached, tracked } from "@glimmer/tracking";
import { service } from "@ember/service";
import helperFn from "discourse/helpers/helper-fn";
import DUserLink from "discourse/ui-kit/d-user-link";
import dAvatar from "discourse/ui-kit/helpers/d-avatar";
import { i18n } from "discourse-i18n";

export default class TopicPresenceDisplay extends Component {
  @service presence;
  @service currentUser;

  @tracked replyChannel;
  @tracked whisperChannel;

  setupReplyChannel = helperFn((_, on) => {
    const { topic } = this.args;

    if (!topic) {
      return;
    }

    const name = `/discourse-presence/reply/${topic.id}`;
    const replyChannel = this.presence.getChannel(name);
    this.replyChannel = replyChannel;

    replyChannel.subscribe();
    on.cleanup(() => replyChannel.unsubscribe());
  });

  setupWhisperChannel = helperFn((_, on) => {
    const { topic } = this.args;
    const { whisperer } = this.currentUser;

    if (!topic || !whisperer) {
      return;
    }

    const name = `/discourse-presence/whisper/${topic.id}`;
    const whisperChannel = this.presence.getChannel(name);
    this.whisperChannel = whisperChannel;

    whisperChannel.subscribe();
    on.cleanup(() => whisperChannel.unsubscribe());
  });

  @cached
  get users() {
    const replyUsers = this.replyChannel?.users || [];
    const whisperUsers = this.whisperChannel?.users || [];

    return [...replyUsers, ...whisperUsers].filter(
      (u) => u.id !== this.currentUser.id
    );
  }

  <template>
    {{#if this.currentUser}}
      {{this.setupReplyChannel}}
      {{this.setupWhisperChannel}}

      {{#if (gt this.users.length 0)}}
        <div class="presence-users">
          <div class="presence-avatars">
            {{#each this.users as |user|}}
              <DUserLink @user={{user}}>
                {{dAvatar user imageSize=@avatarSize}}
              </DUserLink>
            {{/each}}
          </div>

          <span class="presence-text">
            <span class="description">
              {{i18n "presence.replying_to_topic" count=this.users.length}}
            </span>
            <span class="wave">
              <span class="dot">.</span>
              <span class="dot">.</span>
              <span class="dot">.</span>
            </span>
          </span>
        </div>
      {{/if}}
    {{/if}}
  </template>
}
import ComposerPresenceDisplay from "discourse/plugins/discourse-presence/discourse/components/composer-presence-display";

const Presence = <template>
  <div class="before-composer-controls-outlet presence">
    <ComposerPresenceDisplay @model={{@outletArgs.model}} />
  </div>
</template>;

export default Presence;
import Component from "@glimmer/component";
import { concat } from "@ember/helper";
import { trustHTML } from "@ember/template";
import { translateSize } from "discourse/lib/avatar-utils";
import TopicPresenceDisplay from "discourse/plugins/discourse-presence/discourse/components/topic-presence-display";

const AVATAR_SIZE = "small";

export default class Presence extends Component {
  get avatarDimensions() {
    return translateSize(AVATAR_SIZE);
  }

  <template>
    <div
      class="topic-above-footer-buttons-outlet presence"
      style={{trustHTML
        (concat "--avatar-min-height: " this.avatarDimensions "px")
      }}
    >
      <TopicPresenceDisplay
        @avatarSize={{AVATAR_SIZE}}
        @topic={{@outletArgs.model}}
      />
    </div>
  </template>
}
import { withPluginApi } from "discourse/lib/plugin-api";

const PLUGIN_ID = "discourse-presence";

export default {
  name: "presence-admin-plugin-configuration-nav",

  initialize(container) {
    const currentUser = container.lookup("service:current-user");
    if (!currentUser?.admin) {
      return;
    }

    withPluginApi((api) => {
      api.setAdminPluginIcon(PLUGIN_ID, "eye");
    });
  },
};
import { cancel, debounce } from "@ember/runloop";
import Service, { service } from "@ember/service";
import { isTesting } from "discourse/lib/environment";

const KEEP_ALIVE = 10 * 1000; // 10 seconds

export default class ComposerPresenceManager extends Service {
  @service currentUser;
  @service presence;

  notifyState(name, replying = true, keepAlive = KEEP_ALIVE) {
    if (!replying) {
      this.leave();
      return;
    }

    if (this.currentUser.user_option.hide_presence) {
      return;
    }

    if (this._name !== name) {
      this.leave();

      this._name = name;
      this._channel = this.presence.getChannel(name);
      this._channel.enter();

      if (!isTesting()) {
        this._autoLeaveTimer = debounce(this, this.leave, keepAlive);
      }
    }
  }

  leave() {
    if (this._autoLeaveTimer) {
      cancel(this._autoLeaveTimer);
      this._autoLeaveTimer = null;
    }

    this._channel?.leave();
    this._channel = null;
    this._name = null;
  }
}
import * as Mod1 from "./discourse/components/composer-presence-display";
import * as Mod2 from "./discourse/components/topic-presence-display";
import * as Mod3 from "./discourse/connectors/before-composer-controls/presence.gjs";
import * as Mod4 from "./discourse/connectors/topic-above-footer-buttons/presence.gjs";
import * as Mod5 from "./discourse/initializers/presence-admin-plugin-configuration-nav";
import * as Mod6 from "./discourse/services/composer-presence-manager";
const compatModules = {
  "discourse/components/composer-presence-display": Mod1,
  "discourse/components/topic-presence-display": Mod2,
  "discourse/connectors/before-composer-controls/presence": Mod3,
  "discourse/connectors/topic-above-footer-buttons/presence": Mod4,
  "discourse/initializers/presence-admin-plugin-configuration-nav": Mod5,
  "discourse/services/composer-presence-manager": Mod6,
};
export { compatModules };
export default compatModules;
